// Generated by esquadro: do not edit. Formatted text (@rest(html)): edited
// with a rich text editor, shown formatted and cleaned, and as plain text
// where a line is all there is (lists, filters).
import { EditorContent, useEditor, useEditorState, type Editor } from "@tiptap/react"
import StarterKit from "@tiptap/starter-kit"
import DOMPurify from "dompurify"
import {
  Bold,
  Code2,
  Heading2,
  Heading3,
  Italic,
  Link2,
  List,
  ListOrdered,
  Quote,
  Redo2,
  Strikethrough,
  Underline,
  Undo2,
  type LucideIcon,
} from "lucide-react"
import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { t } from "./i18n.ts"

export { plainText } from "./plain.ts"

/** How formatted text looks, in the editor and on a record's page. */
export const RICH =
  "text-sm leading-relaxed text-foreground [&_a]:font-medium [&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4 " +
  "[&_blockquote]:border-l-4 [&_blockquote]:border-border [&_blockquote]:pl-4 [&_blockquote]:text-muted-foreground " +
  "[&_code]:rounded [&_code]:bg-muted [&_code]:px-1 [&_code]:font-mono [&_code]:text-[0.85em] " +
  "[&_h1]:text-xl [&_h1]:font-bold [&_h2]:text-lg [&_h2]:font-bold [&_h3]:text-base [&_h3]:font-bold " +
  "[&_hr]:border-border [&_ol]:list-decimal [&_ol]:pl-5 [&_ul]:list-disc [&_ul]:pl-5 " +
  "[&_pre]:rounded-lg [&_pre]:bg-muted [&_pre]:p-3 [&_pre_code]:bg-transparent [&_pre_code]:p-0 " +
  "[&>*+*]:mt-3"

/** Formatted text, cleaned of anything that could run, as it is shown. */
export function RichText({ html, className }: { html: string; className?: string }) {
  const clean = DOMPurify.sanitize(html, { USE_PROFILES: { html: true }, FORBID_TAGS: ["style", "img", "iframe", "form"], FORBID_ATTR: ["style"] })
  return <div className={cn(RICH, className)} dangerouslySetInnerHTML={ { __html: clean } } />
}

/** A button of the toolbar: what it does, and whether it is on. */
function Tool({ icon: Icon, label, active, disabled, onClick }: { icon: LucideIcon; label: string; active?: boolean; disabled?: boolean; onClick: () => void }) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-sm"
      aria-label={label}
      title={label}
      aria-pressed={active}
      disabled={disabled}
      className={cn("text-muted-foreground", active && "bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary")}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onClick}
    >
      <Icon />
    </Button>
  )
}

/** The link of the selection: set, changed or taken off. */
function LinkTool({ editor, active }: { editor: Editor; active: boolean }) {
  const [open, setOpen] = useState(false)
  const [href, setHref] = useState("")
  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        if (o) setHref(editor.getAttributes("link").href ?? "")
        setOpen(o)
      }}
    >
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={t("richLink")}
          title={t("richLink")}
          aria-pressed={active}
          className={cn("text-muted-foreground", active && "bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary")}
          onMouseDown={(e) => e.preventDefault()}
        >
          <Link2 />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="flex w-80 flex-col gap-2 p-3">
        <form
          className="flex gap-2"
          onSubmit={(e) => {
            e.preventDefault()
            const chain = editor.chain().focus().extendMarkRange("link")
            if (href.trim()) chain.setLink({ href: href.trim() }).run()
            else chain.unsetLink().run()
            setOpen(false)
          }}
        >
          <Input autoFocus placeholder="https://" value={href} onChange={(e) => setHref(e.target.value)} />
          <Button type="submit" size="sm">
            {t("ok")}
          </Button>
        </form>
        {active && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="self-start text-destructive hover:text-destructive"
            onClick={() => {
              editor.chain().focus().extendMarkRange("link").unsetLink().run()
              setOpen(false)
            }}
          >
            {t("richUnlink")}
          </Button>
        )}
      </PopoverContent>
    </Popover>
  )
}

/** A rich text editor in the form: its toolbar, and the text as HTML. */
export function RichTextInput({
  id,
  value,
  onChange,
  invalid,
  max,
}: {
  id: string
  value: string
  onChange: (html: string | null) => void
  invalid?: boolean
  max?: number
}) {
  const editor = useEditor({
    extensions: [StarterKit.configure({ link: { openOnClick: false, autolink: true, defaultProtocol: "https" }, heading: { levels: [1, 2, 3] } })],
    content: value,
    immediatelyRender: true,
    editorProps: { attributes: { id, class: cn(RICH, "min-h-36 px-3 py-2.5 outline-none"), "aria-invalid": invalid ? "true" : "false" } },
    onUpdate: ({ editor }) => onChange(editor.isEmpty ? null : editor.getHTML()),
  })
  // A value from outside (the form reset, a draft): the editor follows it.
  useEffect(() => {
    if (editor && !editor.isFocused && value !== editor.getHTML() && !(editor.isEmpty && !value)) {
      editor.commands.setContent(value ?? "", { emitUpdate: false })
    }
  }, [editor, value])
  const state = useEditorState({
    editor,
    selector: ({ editor: e }) => ({
      bold: e.isActive("bold"),
      italic: e.isActive("italic"),
      underline: e.isActive("underline"),
      strike: e.isActive("strike"),
      h2: e.isActive("heading", { level: 2 }),
      h3: e.isActive("heading", { level: 3 }),
      bullet: e.isActive("bulletList"),
      ordered: e.isActive("orderedList"),
      quote: e.isActive("blockquote"),
      code: e.isActive("codeBlock"),
      link: e.isActive("link"),
      undo: e.can().undo(),
      redo: e.can().redo(),
      length: e.getText().length,
    }),
  })
  if (!editor || !state) return null
  const run = (f: (c: ReturnType<Editor["chain"]>) => ReturnType<Editor["chain"]>) => f(editor.chain().focus()).run()
  return (
    <div
      className={cn(
        "rounded-lg border border-input bg-transparent shadow-xs transition-[color,box-shadow] focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50",
        invalid && "border-destructive focus-within:ring-destructive/20",
      )}
    >
      <div className="flex flex-wrap items-center gap-0.5 border-b border-border px-1.5 py-1">
        <Tool icon={Bold} label={t("richBold")} active={state.bold} onClick={() => run((c) => c.toggleBold())} />
        <Tool icon={Italic} label={t("richItalic")} active={state.italic} onClick={() => run((c) => c.toggleItalic())} />
        <Tool icon={Underline} label={t("richUnderline")} active={state.underline} onClick={() => run((c) => c.toggleUnderline())} />
        <Tool icon={Strikethrough} label={t("richStrike")} active={state.strike} onClick={() => run((c) => c.toggleStrike())} />
        <span className="mx-1 h-5 w-px bg-border" />
        <Tool icon={Heading2} label={t("richHeading")} active={state.h2} onClick={() => run((c) => c.toggleHeading({ level: 2 }))} />
        <Tool icon={Heading3} label={t("richSubheading")} active={state.h3} onClick={() => run((c) => c.toggleHeading({ level: 3 }))} />
        <Tool icon={List} label={t("richBullets")} active={state.bullet} onClick={() => run((c) => c.toggleBulletList())} />
        <Tool icon={ListOrdered} label={t("richNumbers")} active={state.ordered} onClick={() => run((c) => c.toggleOrderedList())} />
        <Tool icon={Quote} label={t("richQuote")} active={state.quote} onClick={() => run((c) => c.toggleBlockquote())} />
        <Tool icon={Code2} label={t("richCode")} active={state.code} onClick={() => run((c) => c.toggleCodeBlock())} />
        <LinkTool editor={editor} active={state.link} />
        <span className="ml-auto flex items-center gap-0.5">
          <Tool icon={Undo2} label={t("richUndo")} disabled={!state.undo} onClick={() => run((c) => c.undo())} />
          <Tool icon={Redo2} label={t("richRedo")} disabled={!state.redo} onClick={() => run((c) => c.redo())} />
        </span>
      </div>
      <EditorContent editor={editor} />
      {max !== undefined && (
        <p className={cn("px-3 pb-2 text-right text-xs text-muted-foreground tabular-nums", state.length > max && "text-destructive")}>
          {state.length} / {max}
        </p>
      )}
    </div>
  )
}
